async def act(page):
    """
    Navigate to the Product Views report and set the date range from 07/05/2021 to 05/31/2023,
    then trigger the report generation.
    """
    # Step 1: Navigate to the product views report (relative path)
    await page.goto('/index.php/admin/report/product/viewed/')
    await page.wait_for_load_state('networkidle')

    # Step 2: Try to locate 'From' and 'To' textboxes by accessible name and fill them.
    from_box = page.get_by_role('textbox', name='From')
    to_box = page.get_by_role('textbox', name='To')

    from_filled = False
    to_filled = False

    if await from_box.count() > 0:
        await from_box.nth(0).fill('07/05/2021')
        from_filled = True

    if await to_box.count() > 0:
        await to_box.nth(0).fill('05/31/2023')
        to_filled = True

    # Step 2b: Fallback - use the first two textboxes on the page if labeled ones aren't present
    if not (from_filled and to_filled):
        textboxes = page.get_by_role('textbox')
        n_textboxes = await textboxes.count()
        if n_textboxes >= 2:
            if not from_filled:
                await textboxes.nth(0).fill('07/05/2021')
                from_filled = True
            if not to_filled:
                await textboxes.nth(1).fill('05/31/2023')
                to_filled = True
        elif n_textboxes == 1:
            # Some UIs combine the range in a single textbox; try to set both values conservatively.
            if not from_filled:
                await textboxes.nth(0).fill('07/05/2021')
                from_filled = True
            if not to_filled:
                try:
                    await textboxes.nth(0).press('End')
                    # Attempt to append a separator and the to-date; narrow attempt only.
                    await textboxes.nth(0).type(' - 05/31/2023')
                    to_filled = True
                except Exception:
                    to_filled = False

    # Step 3: Click the button to generate the report. Prefer 'Show Report', then fallbacks.
    clicked = False

    show_report_btn = page.get_by_role('button', name='Show Report')
    if await show_report_btn.count() > 0:
        try:
            await show_report_btn.nth(0).click()
            clicked = True
        except Exception:
            clicked = False

    if not clicked:
        show_btn = page.get_by_role('button', name='Show')
        if await show_btn.count() > 0:
            try:
                await show_btn.nth(0).click()
                clicked = True
            except Exception:
                clicked = False

    if not clicked:
        refresh_btn = page.get_by_role('button', name='Refresh')
        if await refresh_btn.count() > 0:
            try:
                await refresh_btn.nth(0).click()
                clicked = True
            except Exception:
                clicked = False

    # Step 4: As a last resort, submit an enclosing form region that contains a textbox.
    if not clicked:
        forms = page.get_by_role('form')
        if await forms.count() > 0:
            c = await forms.count()
            for i in range(c):
                frm = forms.nth(i)
                if await frm.get_by_role('textbox').count() > 0:
                    try:
                        form_handle = await frm.element_handle()
                        if form_handle is not None:
                            await page.evaluate('(form) => form.submit()', form_handle)
                            clicked = True
                            break
                    except Exception:
                        # Narrowly ignore JS submission failures and continue trying other fallbacks
                        clicked = False

    # Step 5: Wait briefly for the report to render/update
    await page.wait_for_timeout(1500)

    # End: The Product Views report page should now reflect the requested date range.

